begin;
create function internal.read_intelligence_metrics(window_days integer,target_mode text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();completed integer;failed integer;grounded integer;decided integer;approved integer;finished integer;measured integer;improved integer;latency numeric;cost_total numeric;answer jsonb;
begin
 if not"authorization".improvement_access(school)or"authorization".current_role(school)not in('admin','teacher','coordinator')then raise exception 'Intelligence metrics denied'using errcode='42501';end if;
 if window_days not between 1 and 365 or target_mode not in('FIXTURE','LIVE')then raise exception 'Bounded metric window required'using errcode='22023';end if;
 with runs as materialized(select ir.*from app.intelligence_runs ir where ir.school_id=school and ir.generation_mode=target_mode and ir.created_at>=clock_timestamp()-make_interval(days=>window_days)and"authorization".can_manage_baseline(school,ir.baseline_result_id)), sources as materialized(select ir.state,ir.evaluation_status,ir.latency_ms,ir.cost,q.status proposal_status,i.status intervention_status,outcome.status outcome_status from runs ir left join app.recommendations q on q.school_id=ir.school_id and q.intelligence_run_id=ir.id left join app.interventions i on i.school_id=q.school_id and i.recommendation_id=q.id left join app.outcome_measurements outcome on outcome.school_id=i.school_id and outcome.intervention_id=i.id)
 select count(*)filter(where state='PROPOSAL_READY'),count(*)filter(where state='FAILED'),count(*)filter(where evaluation_status='PASSED'),count(*)filter(where proposal_status in('APPROVED','REJECTED')),count(*)filter(where proposal_status='APPROVED'),count(*)filter(where intervention_status in('COMPLETED','MEASURED')),count(*)filter(where outcome_status is not null),count(*)filter(where outcome_status='improved'),avg(latency_ms)filter(where state='PROPOSAL_READY'),coalesce(sum(cost)filter(where state='PROPOSAL_READY'),0)into completed,failed,grounded,decided,approved,finished,measured,improved,latency,cost_total from sources;
 answer:=jsonb_build_object('windowDays',window_days,'mode',target_mode,'scope','CURRENT_AUTHORIZED_RUNS','completedRuns',completed,'failedRuns',failed,'groundedResponse',jsonb_build_object('numerator',grounded,'denominator',completed,'rate',case when completed=0 then null else grounded::numeric/completed end),'acceptance',jsonb_build_object('numerator',approved,'denominator',decided,'rate',case when decided=0 then null else approved::numeric/decided end),'completion',jsonb_build_object('numerator',finished,'denominator',approved,'rate',case when approved=0 then null else finished::numeric/approved end),'observedImprovement',jsonb_build_object('numerator',improved,'denominator',measured,'rate',case when measured=0 then null else improved::numeric/measured end),'meanLatencyMs',latency,'totalCost',cost_total,'costPerApprovedWorkflow',case when approved=0 then null else cost_total/approved end,'unsupportedClaimRate',null,'unauthorizedContextLeakageRate',null,'invalidToolCallRate',null,'humanOverrideRate',null,'unknownMetricReason','NO_DEDICATED_OBSERVATION_DENOMINATOR');return answer;
end$$;
revoke execute on function internal.read_intelligence_metrics(integer,text)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.read_intelligence_metrics(integer,text)to cuevo_api;
commit;
